def centered (q : MvPolynomial (σ ⊕ ι) ℂ) (j : ι → Fin 2)
    (b : P → σ → ℂ) (h : P → ι → ℂ) (p : P) : Poly :=
  eval₂Hom C (Sum.elim (fun i => C (b p i)) (fun i => X (j i) + C (h p i))) q

